// Pola untuk kalimat yang berisi nama, bukan hanya angka.
const SITE = { 'Dekat kawah gelap': 'Near the dark crater', 'Puncak bukit': 'Ridge top' };
export const RULES = [
  [/^(Dekat kawah gelap|Puncak bukit): (\d+) u ke (kanan|kiri) (→|←)$/, (m) => `${SITE[m[1]]}: ${m[2]} u to the ${m[3] === 'kanan' ? 'right' : 'left'} ${m[4]}`],
  [/^(Dekat kawah gelap|Puncak bukit) (\d+) u$/, (m) => `${SITE[m[1]]} ${m[2]} u`],
  [/^Bahan bakar (\d+)% · pendarat (\d+)%$/, 'Fuel $1% · lander $2%'],
  [/^Bahan bakar roket pendarat (\d+)%$/, 'Landing rocket fuel $1%'],
  [/^Roket: (kecil|sedang|besar)$/, (m) => `Rocket: ${{ kecil: 'small', sedang: 'medium', besar: 'large' }[m[1]]}`],
  [/^Room (\w{4})$/, 'Room $1'],
];

export const WORDS = { roket: 'rocket', kecil: 'small', sedang: 'medium', besar: 'large', kapsul: 'capsule', pendarat: 'lander' };

