RULES.push(
  [/^Tambah Gas \+ sampai (\d+)%! (.+)$/, (m, tr) => `Add Throttle + up to ${m[1]}%! ${tr(m[2])}`],
  [/^Terlalu miring: (\d+)° \(maks\. (\d+)° di (Dekat kawah gelap|Puncak bukit)\)\. Pendarat terguling\.$/, (m) => `Too tilted: ${m[1]}° (max ${m[2]}° at ${SITE[m[3]]}). The lander tips over.`],
  [/^(Terlalu cepat turun!|Kecepatan menyamping belum pas!|Pendarat naik\.|Mengerem:.*?\.) Tekan Gas \+ \(sampai (\d+)%\)\.$/, (m, tr) => `${tr(m[1])} Press Throttle + (up to ${m[2]}%).`],
  [/^Antena: (.+) \((\d)\)$/, (m, tr) => `Antenna: ${tr(m[1])} (${m[2]})`],
  [/^Spektrometer: (.+) \((\d)\)$/, (m, tr) => `Spectrometer: ${tr(m[1])} (${m[2]})`],
);

